// Regenerates src/shared/infrastructure/tenancy/tenant-model-map.ts from the
// Prisma schema. Run after changing the schema:
//   node scripts/tenancy/generate-tenant-model-map.mjs
import { writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { readTenantModelMap } from "./read-tenant-model-map.mjs";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const { tenantModels, relations } = readTenantModelMap(path.join(root, "prisma/schema.prisma"));

const lines = [
  "// GENERATED by scripts/tenancy/generate-tenant-model-map.mjs — do not edit.",
  "// A test fails if this drifts from prisma/schema.prisma.",
  "",
  "/** Models whose rows belong to one organization (have organizationId). */",
  "export const TENANT_MODELS: ReadonlySet<string> = new Set([",
  ...tenantModels.map((model) => `  "${model}",`),
  "]);",
  "",
  "/** Relation fields per model: field name → related model. */",
  "export const MODEL_RELATIONS: Readonly<Record<string, Readonly<Record<string, string>>>> = {",
  ...Object.entries(relations)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([model, fields]) => {
      const entries = Object.entries(fields)
        .sort(([a], [b]) => a.localeCompare(b))
        .map(([field, target]) => `${field}: "${target}"`)
        .join(", ");
      return `  ${model}: { ${entries} },`;
    }),
  "};",
  "",
];

const out = path.join(root, "src/shared/infrastructure/tenancy/tenant-model-map.ts");
writeFileSync(out, lines.join("\n"));
console.log(`tenant models: ${tenantModels.length}, models: ${Object.keys(relations).length}`);
